// GET /products?page=0&size=20&sort=price,desc&category=books
@GetMapping("/products")
public Page<ProductResponse> list(@RequestParam(required = false) String category,
                                  @PageableDefault(size = 20) Pageable pageable) {
    Page<Product> page = (category == null)
        ? repository.findAll(pageable)                     // no filter: everything
        : repository.findByCategory(category, pageable);
    return page.map(ProductResponse::from);
}

@RestControllerAdvice
public class ApiExceptionHandler {
    @ExceptionHandler(OrderNotFoundException.class)
    ProblemDetail notFound(OrderNotFoundException ex) {
        ProblemDetail pd = ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, ex.getMessage());
        pd.setTitle("Order not found");
        return pd;
    }
}

// Response (application/problem+json):
